1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	import 'package:fpdart/fpdart.dart';
5	
6	import '../../../../core/failure/failure.dart';
7	import '../../domain/entities/chat_message.dart';
8	import '../../domain/entities/chat_session.dart';
9	import '../../domain/entities/chat_stream_event.dart';
10	import '../../domain/repositories/chat_repository.dart';
11	import 'chat_state.dart';
12	
13	/// Drives `ChatScreen` — a DI `lazySingleton` (Code Map, mirroring
14	/// `MeusRegistrosCubit`): long-lived, so returning to Home/Chat within the
15	/// same app session never re-bootstraps the session/history it already
16	/// loaded (`init()`'s own no-op guard below).
17	class ChatCubit extends Cubit<ChatState> {
18	  ChatCubit(this._repository) : super(const ChatBootstrapLoading());
19	
20	  final ChatRepository _repository;
21	
22	  StreamSubscription<Either<Failure, ChatStreamEvent>>? _sendSubscription;
23	
24	  /// Monotonic counter behind every locally generated [ChatUiMessage.id]
25	  /// (Code Map) — never the server's own message id (see `ChatStreamEvent`'s
26	  /// own doc on why `message_created`'s id goes unused here).
27	  int _localIdCounter = 0;
28	
29	  /// Boundaries: "On opening Home/Chat, silently ensure one Chat Session
30	  /// exists (reuse the most recent from `chat-sessions-list`, else
31	  /// `chat-sessions-create` with no title)". A no-op once already
32	  /// [ChatReady] — `ChatScreen.initState()` calls this unconditionally on
33	  /// every mount, but a `lazySingleton` cubit may already be bootstrapped
34	  /// from an earlier visit.
35	  Future<void> init() async {
36	    if (state is ChatReady) {
37	      return;
38	    }
39	    if (isClosed) {
40	      return;
41	    }
42	    emit(const ChatBootstrapLoading());
43	
44	    final sessionsResult = await _repository.listSessions();
45	    if (isClosed) {
46	      return;
47	    }
48	    final Either<Failure, ChatSession> sessionResult = await sessionsResult
49	        .match((failure) async => left(failure), (sessions) async {
50	          if (sessions.isEmpty) {
51	            return _repository.createSession();
52	          }
53	          // "reuse the most recent" — defensively re-sorts rather than
54	          // trusting `listSessions()`'s own ordering (its offline-cache
55	          // fallback already sorts `updatedAt` desc, but the live
56	          // server response's own ordering isn't documented either
57	          // way).
58	          final mostRecent = [...sessions]
59	            ..sort((a, b) => b.updatedAt.compareTo(a.updatedAt));
60	          return right(mostRecent.first);
61	        });
62	    if (isClosed) {
63	      return;
64	    }
65	
66	    await sessionResult.match(
67	      (failure) async {
68	        if (!isClosed) {
69	          emit(ChatBootstrapError(failure));
70	        }
71	      },
72	      (session) async {
73	        final messagesResult = await _repository.listMessages(session.id);
74	        if (isClosed) {
75	          return;
76	        }
77	        messagesResult.match(
78	          (failure) => emit(ChatBootstrapError(failure)),
79	          (messages) => emit(
80	            ChatReady(
81	              sessionId: session.id,
82	              messages: messages.map(_fromDomain).toList(),
83	            ),
84	          ),
85	        );
86	      },
87	    );
88	  }
89	
90	  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
91	    id: message.id,
92	    role: message.role,
93	    content: message.content,
94	    status: message.status,
95	  );
96	
97	  /// Boundaries: optimistic user bubble, then subscribes to
98	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
99	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
100	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
101	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
102	  ///
103	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
104	  /// or failed — the composer is disabled in that case anyway), while
105	  /// [content] is blank once trimmed, or while an earlier call's AI
106	  /// bubble is still `streaming` — this story never races two concurrent
107	  /// sends against the one in-memory session (Boundaries: no offline
108	  /// lock/composer-disable UI of its own exists yet, Story 6.3's job, so
